   "page": 3,
   "contexte": "La société REF+ connait depuis sa création un développement important qui la place aujourd’hui en bonne position sur le marché français du référencement. Cependant, depuis quelques mois à la suite de la perte d’un grand nombre de clients, elle constate une baisse de son chiffre d’affaires. En effet, ces clients sont attirés par les prix anormalement faibles pratiqués par l’entreprise WEBREFY, leader sur le marché français du référencement. Compte tenu de ses coûts, la société REF+ ne peut aligner ses prix sur ceux de son concurrent. Monsieur MELASTE soupçonne ses concurrent WEREFY d’avoir recours à des pratiques anticoncurrentielles sur le marché du référencement.",
