   "page": 4,
   "contexte": "Depuis mai 2023, de nombreux concurrents, éditeurs de logiciels, présentent leur candidature pour l’immatriculation de leur plateforme PDP auprès de l’État. L’un d’entre eux, l’ éditeur INTENSO, a déposé un dossier pour une plateforme appelée BILLFACTO. DIGIM, qui a déposé précédemment la marque presque similaire BILLFACT en 2020, s’interroge sur les recours juridiques envisageables.",
