   "dossier": "",
   "mission": "Mission 2 : La stratégie d’intégration d’OVHcloud, source de contraintes et d’opportunités",
   "page": 5,
   "contexte": "Opter pour une stratégie d’intégration nécessite des besoins en personnel importants auxquels OVHcloud doit faire face. L’entreprise publie régulièrement des offres d’emploi sur son site internet. Sébastien Casares, actuellement employé en qualité de développeur chez XTCcloud, un concurrent direct implanté à Lille dans la Région Hauts-de-France, envisage de postuler chez OVHcloud, au siège social de Roubaix. Il s’interroge sur la possibilité de démontrer ses com pétences au recruteur d’OVHcloud en proposant d’utiliser un logiciel développé à la demande de son supérieur hiérarchique chez XTCcloud. Sébastien Casares a travaillé seul sur ce projet et y a consacré en plus de ses heures de travail la majorité de son temps libre.",
   "texte": "Déterminer, à l’aide d’un raisonnement juridique, si Sébastien Casares est titulaire des droits sur le logiciel.",
