   "num": "3.3",
   "dossier": "",
   "mission": "Mission 3 : Les risques liés à l’activité de l’entreprise OVHcloud",
   "page": 6,
   "contexte": "La société Bati Courtage a souscrit un contrat d’hébergement simple avec une option supplémentaire de sauvegarde des données chez OVHCLOUD . Cet te option consiste à stocker les données du client sur un support externe au système principal. Un incendie survenu le 09 mars 2021 a engendré la destruction complète des data centers d’OVHcloud à Strasbourg. Bati Courtage a perdu de manière irréversible l’intégralité des données stockées chez l’hébergeur. Les conséquences financières pour l’entreprise ont été t rès lourdes, ce qui a poussé le responsable de Bati Courtage à engager un recours en justice contre OVHcloud pour réclamer une indemnisation du préjudice subi.",
   "texte": "Expliquer, à l’aide d’un raisonnement juridique, pourquoi la responsabilité civile contractuelle d’OVHcloud a été engagée.",
