   "contexte": "",
   "texte": "a) Indiquer pourquoi la configuration en RAID niveau 0 n’assure pas la sureté des données. b) Proposer le niveau RAID à utiliser sur le serveur NAS qui assurerait la meilleu re sureté tout en répondant aux contraintes de volume. Vous justifierez votre réponse notamment par le calcul du volume utile.",
