   "mission": "",
   "page": 7,
   "contexte": "Le serveur « Windows2016 » stocke ses données sur une grappe locale de disques configurée en RAID niveau 5, composée de 3 disques de 4 To.",
   "texte": "Expliquer pourquoi il est nécessaire de faire des sauvegardes du serveur « Windows2016 » vers le serveur NAS.",
