   "sujet": "E7_SISR_2022_Myon-Nouvelle-Caledonie",
   "num": "B1.3",
   "dossier": "DOSSIER B : SÉCURISATION DES SERVEURS ET DES SERVICES",
   "mission": "",
   "page": 7,
   "contexte": "Le serveur NAS étant situé dans le même local que les autres serveurs, il serait souhaitable d'avoir une sauvegarde du serveur NAS sur un serveur éloigné physiquement de Lesquin. Pour cela, vous proposez la location d'un serveur dédié chez l’hébergeur français PWI.",
   "texte": "Donner au moins un élément juridique et un élément technique à Mme Carlier qui justifient le choix d’un hébergeur français.",
