   "mission": "",
   "page": 7,
   "contexte": "Les serveurs proposés par l’hébergeur PWI permettent d’utiliser les protocoles de communication suivants : HTTP, HTTPS, FTP, FTPS, SFTP, SSH, SCP",
   "texte": "Proposer un protocole sécurisé pour transférer les données entre Lesquin et la nouvelle solution de stockage. Justifier la réponse.",
