   "mission": "Mission B2 – Mise en place de délégation de droits",
   "page": 8,
   "contexte": "La faille de sécurité décrite peut être corrigée en appliquant la mesure préconisée à savoir la mise à jour vers la dernière version de l’utilitaire. Un script a été récupéré sur le site web officiel de l’utilitaire sudo. Avant de l’exécuter, madame Carlier vous demande de vérifier les actions de ce script.",
