   "contexte": "Dans un contexte de transport routier très concurrentiel, cette évolution est essentielle pour l’entreprise. Chaque salarié(e) s’est vu remettre une procédure concernant le chiffrement des courriels. Vous devez préparer une réunion pour expliquer cette évolution à la direction de l’entreprise.",
