   "mission": "Mission A1 – Vérification des accès au réseau",
   "page": 4,
   "contexte": "Les personnels de la mairie sont considérés comme des utilisateurs loyaux et fiables, ils n’accèdent qu’aux applications et ressources qui leur sont nécessaires pour effectuer leur tra vail. M. Hopada s’interroge sur la possibilité d’accès malveillant aux données de la mairie par des personnes externes à l’organisation.",
   "texte": "Indiquer au moins trois cas de figure permettant l’accès d’une personne malveillante aux postes de travail ou aux comptes personnels des personnels de la mairie.",
