   "sujet": "E7_SISR_2023_Saint-Jacques-Nouvelle-Caledonie",
   "num": "A1.4",
   "dossier": "Dossier A – Audit général de la sécurité du réseau",
   "mission": "Mission A1 – Vérification des accès au réseau",
   "page": 4,
   "contexte": "Le technicien s’est rendu compte que l’adresse MAC de la carte réseau du poste concerné a été modifiée, afin que ce dernier appartienne au « VLAN » de la mairie, permettant ainsi l’impression.",
   "texte": "Proposer une nouvelle stratégie permettant de garantir le cloisonnement des ordinateurs de la médiathèque au sein du réseau local virtuel (VLAN) approprié, sans ajouter de matériel d’interconnexion ou de service supplémentaire.",
