   "page": 6,
   "contexte": "Dans le plan actuel, l e lieu de sauvegarde est unique. Dans le cas d’une éventuelle attaque simultanée sur le site principal et sur le site de secours, le système d’information serait donc exposé à un risque de perte de données.",
