   "mission": "Mission B2 – Sécurisation des liaisons avec les sites distants",
   "page": 8,
   "contexte": "M. Hopada n’est pas un spécialiste des technologies VPN. Il a des compétences théoriques concernant les chiffrements symétrique et asymétrique mais ne comprend pas le fonctionnement du chiffrement des données décrit dans la phase 2 du document B1 - Concepts et généralités VPN IPSec : « […] chaque extrémité possédera les deux clés symétriques : une pour chiffrer les données transmises et l’autre pour déchiffrer les données reçues… ».",
   "texte": "Représenter à l’aide d’un schéma détaillé l’utilisation des deux clés symétriques, nommées et citées en phase 2 dans le document B1, en indiquant le processus de chiffrement et de déchiffrement des données. Vous préciserez le rôle de chaque clé lors de l’envoi et de la réception des flux pour les deux équipements concernés.",
