   "mission": "Mission A2 – Évaluer les risques numériques",
   "page": 4,
   "contexte": "Afin de limiter les risques liés à un rançongiciel, M. Aurat vous demande d’analyser deux solutions pour les postes de travail intégrées au système d’ex ploitation Windows : « Application Guard » et « Sandbox » (bac à sable).",
   "texte": "Indiquer l’impact sur la gravité et sur la vraisemblance de chacune des solutions « Bac à sable » et « Application Guard » pour le risque induit par un rançongiciel. Justifier la réponse. 3 Technique d’attaque courante de la cybercriminalité, le rançongiciel consiste en l’envoi à la victime d’un logiciel malveillant qui chiffre l’ensemble de ses données et lui demande une rançon en échange du mot de passe de déchiffrement. (source :",
