   "contexte": "Avant de modifier la stratégie de mots de passe du domaine, l’administrateur veut connaitre l’impact de la mise à jour sur les utilisateurs. Il voudrait notamment connaitre la liste des utilisateurs à privilèges qui devront renouveler leur mot de passe. Vous prenez en charge la récupération de cette information en utilisant un script Powershell. Un script ayant une autre fonction vous est présenté dans le dossier documentaire.",
   "texte": "Adapter le script Powershell afin de permettre de lister les comptes à privilèges appartenant au groupe « Administrateurs de l'entreprise » dont le mot de passe n’a pas été modifié depuis plus d’un an.",
