   "dossier": "Dossier B – Mesures de protection supplémentaires face aux menaces",
   "mission": "Mission B3 – Sécuriser le réseau local de la bibliothèque",
   "page": 6,
   "contexte": "Sur les 42 prises, 38 sont utilisées (prises B01 à B38) pour les postes PC de la bi bliothèque et 4 sont inutilisées (prises B39 à B42). Toutes sont brassées sur les ports d’un commutateur (situé dans une baie de brassage) en respectant le numéro de la prise et le numéro de l’interface (prise B0 5 brassée sur l’interface fa0/5 du commutateur). L’administrateur du pôle PSIR a décidé de sécuriser les ports en limitant l’accès aux seules machines de la bibliothèque sans avoir à collecter manuellement l’ensemble des adresses MAC.",
   "texte": "a) Lister les actions à entreprendre sur le commut ateur de la bibliothèque afin de sécuriser les 42 prises murales. b) Écrire les commandes à saisir sur le commutateur pour réaliser ces actions.",
