   "dossier": "Dossier C – Réponse à un incident de sécurité",
   "mission": "Mission C1 – Analyser et investiguer l’incident",
   "page": 7,
   "contexte": "Lors d’une précédente évaluation des risques, la DSI avait mis en évidence le risque d’hameçonnage et avait, comme mesure principale, choisi la formation et la sensi bilisation des utilisateurs. La phase n° 6 « Enseignements » du plan de réponse à incident amène à tirer les conclusions sur l’incident et les actions de formations déjà menées. Vous participez à la réunion d’analyse post - incident et devez proposer des recommandations de sécurité.",
