   "contexte": "Le directeur des systèmes d’information souhaite obtenir des précisions concernant un certain nombre de points soulevés dans le guide de l’ANSSI.",
   "texte": "Répondre aux interrogations suivantes : a) Indiquer quel est l’intérêt d’effectuer des sauvegardes déconnectées du système d’information et quelle solution matérielle permettrait de les mettre en place. b) Préciser comment il est possible de s’informer régulièrement des dernières failles de sécurité découvertes afin de gagner en réactivité. c) Justifier l’intérêt d’un réseau local virtuel (VLAN) dédié à l’administration réseau dans l’optique du cloisonnement du système d’information. d) Expliquer pourquoi il est recommandé que le ou les poste(s) d’administration n’aient pas accès à internet.",
