   "contexte": "La RSSI vous demande, dans un premier temps, de réaliser une maquette de cette solution de déchiffrement des flux HTTPS. Elle souhaite notamment que toute l’équipe comprenne bien le rôle du service mandataire (proxy) SSL proposé par les solutions de pare -feu Stormshield Network Security (SNS).",
