   "mission": "Mission B1 – Analyser un audit de sécurité de l’annuaire Active Directory (première partie)",
   "page": 6,
   "contexte": "Suite à une sensibilisation à la sécurité effectuée récemment par un partenaire auprès de la majorité des utilisateurs de votre organisation, monsieur Denis BRODIER, responsable des ressources humaines, vous alerte de la fuite de son mot de passe. Le site web haveibeenpwned.com a confirmé ce vol et sa publication. C ette fuite impacte la sécurité de l’ établissement par le statut de cet utilisateur avec pouvoir (il possède des droits supplémentaires) et la réutilisation du même mot de passe auprès de différentes entités dont la clinique MARTIN. Votre hiérarchie vous demande de rappeler certaines bonnes pratiques rattachées à la gestion des mots de passe, ces préconisations seront diffusées par la suite à l’ensemble du personnel.",
   "texte": "a) Expliquer par un exemple concret le danger d’utiliser un mot de passe même complexe de manière répétée. b) Proposer un outil aidant les utilisateurs à respecter la logique « un site = un mot de passe unique » tout en maintenant un bon niveau de sécurité.",
