   "page": 5,
   "contexte": "La communauté de communes souhaite se conformer aux préconisations découlant de l’audit et qui se basent sur les recommandations de l’ANSSI. Vous avez la charge de mettre en place un serveur mandataire inversé ( reverse proxy). Le choix s’est porté sur le pare -feu d’application « NGINX ModSecurity WAF ». Une nouvelle architecture réseau a été établie afin d’améliorer la sécurité des applications web proposées. Pour renforcer la confidentialité, il a été décidé de chiffrer la connexion depuis le client vers le serveur mandataire inv ersé (reverse proxy) puis jusqu’aux serveurs web. Pour cela, une autorité de certification interne a été créée afin de générer un certificat SSL/TLS à usage interne.",
