   "mission": "Mission A1 – Analyse de l'incident et interventions immédiates",
   "page": 4,
   "contexte": "Le micrologiciel (firmware) des commutateurs stocke la table d'adresses MAC (media access control) dans la mémoire RAM interne qui est limitée en taille. Par ailleurs, une analyse de trames réalisée à partir de l’ordinateur ayant l’adresse IP 192.168.10.86 révèle que ce dernier reçoi t des trames à destination de différentes adresses IP du réseau dont quelques-unes sont illustrées dans le dossier documentaire. Le contenu de la table d’adresses MAC, l’extrait de la capture de trames et la documentation sur le fonctionnement des commutateurs pourraient éclairer sur la cause des lenteurs observées.",
   "texte": "a) Préciser quelles sont les trames qui ne devraient pas apparaître sur l’analyse de trame. Justifier la réponse. b) Analyser le contenu de la table d’adresses MAC en fonction de la situation observée, en déduire et expliquer le mode de fonctionnement actuel du commutateur en défaut. c) Expliquer l’impact sur les autres commutateurs et en déduire les conséquences sur le réseau VLAN 10.",
