   "page": 5,
   "contexte": "L’ensemble des commutateurs du cœur de réseau, de distribution et d'accès sont disposés dans une armoire disposant d’un interrupteur d’arrêt d’urgence. L’infrastructure informatique est bloquée au point qu’il est maintenant impossible de vous connecter à l’interface de contrôle des commutateurs. À ce stade il est important de tenter une action d’urgence permettant de retrouver au moins provisoirement une situation normale.",
