   "contexte": "Madame JOUANDEAU vous demande d'activer le portail captif et de mettre en œuvre l a politique de filtrage sur le pare-feu interne nécessaire pour que les clients connectés au réseau Wi-Fi Invité aient accès à internet via les protocoles HTTP et HTTPS. Le principe de fonctionnement de cette solution est décrit dans le dossier documentaire. Bien que certaines règles soient automatiquement générées par le pare -feu lors de l’activation du portail, madame JOUANDEAU souhaite un rapport listant l’ensemble des règles mises en place sur le flux entrant de l’interface Wi-Fi du pare-feu interne, y compris celles créées implicitement, afin de vérifier leur conformité avec les exigences de sécurité.",
