   "contexte": "Lors de la poursuite des investigations, vous lisez que le nombre d'attaques liées à la vulnérabilité Log4j a augmenté de 12 %, soulignant la persistance de cette menace. Toujours dans le cadre de l’analyse forensique, vous êtes chargé(e) d’évaluer si le serveur web hébergeant les applications métiers des collaborateurs (SRV_WEB1), a été compromis par l’exploitation de cette vulnérabilité, ce qui pourrait être le vecteur d’attaque initial utilisé pour déployer le rançongiciel sur le serveur hébergeant le progiciel de gestion intégré (SRV_ERP). Le bulletin d’alerte du réseau CERT.FR publié le 10 décembre 2021 concernant c ette vulnérabilité et un extrait des journaux d’évènements du serveur web vous sont communiqués.",
