   "dossier": "Dossier A – Sécurisation de l'application de formation en ligne (e-learning)",
   "mission": "Mission A3 – Vérification de la sécurité du mot de passe",
   "page": 5,
   "contexte": "Clémence Auroux décide qu'un élève doit renouveler obligatoirement son mot de passe au bout de 3 mois, soit 90 jours. Elle vous charge de mettre en place ce nouveau besoin au niveau de la base de données afin de vérifier, à chaque connexion d’un élève, l’ancienneté de son mot de passe. Le cahier des charges technique qu’elle vous a fourni indique qu’il faut ajouter dans la table Utilisateur un champ obl igatoire dateMajMDP initialisé lors de la création d’un compte. Il faudra également écrire une fonction MySQL renouvelleMDP qui prendra comme paramètre d’entrée l’identifiant d’un élève et retournera vrai si cet élève n’a pas changé son mot de passe depuis plus de 3 mois ou 90 jours.",
