   "mission": "Mission B1 - Attribution de la Garantie Réussite",
   "page": 6,
   "contexte": "Lorsqu’une auto-école enregistre, sur la plateforme, l’échec d’un élève à l’ETG, un déclencheur nommé check_garantie_reussite est exécuté dans la base de données afin de contrôler que toutes les conditions sont remplies pour attribuer la Garantie Réussite. Clémence Auroux vous demande de vérifier et de corriger ce déclencheur (trigger) afin de garantir que cette fonctionnalité ne puisse plus faire l’objet de déclarations malveillantes. Pour ce faire, elle vous fournit la liste des conditions de la Garantie Réussite ainsi que le code source du déclencheur correspondant.",
