   "contexte": "Pour garantir une sécurité optimale et ne pas surcharger la plateforme principale, Clémence Auroux souhaite que les événements sur les données personnelles soient enregistrés dans une base de données spécifique (BD_RGPD_LOGS) localisée sur un serveur physi que différent. Le nom DNS du serveur Web hébergeant le site de l’application est Easy2Drive.fr.",
