   "page": 8,
   "contexte": "",
   "texte": "a) Expliquer le rôle de la méthode before de la classe AuthGuard. b) Expliquer si un attaquant a besoin d’être préalablement authentifié pour insérer un commentaire dans le formulaire de saisie des avis.",
