   "sujet": "E7_SLAM_2023_Lama-Zoo",
   "num": "B2",
   "dossier": "Dossier B : Sécurisation du recueil des avis des participants aux ateliers",
   "mission": "",
   "page": 9,
   "contexte": "",
   "texte": "a) Expliquer pourquoi il s'agit ici d'une attaque XSS stockée. b) Expliquer pourquoi une attaque de type XSS stocké est susceptible de toucher un plus grand nombre de visiteurs du site Web qu'une attaque XSS reflétée.",
