   "contexte": "",
   "texte": "a) Indiquer pour chacune des deux solutions de protection contre les attaques CSRF proposées par l’environnement de développement CodeIgniter les éléments de sécurisation stockés côté client et ceux stockés côté serveur. b) Indiquer les modifications à apporter aux classes Security et Filters afin d’activer la protection CSRF basée sur la session ( Synchronizer token ) et préciser ce que les développeurs des vues devront utiliser dans les formulaires qu'ils veulent protéger.",
