   "contexte": "Les différentes contraintes opérationnelles de l'activité des sapeurs -pompiers les exposent à de hauts risques sanitaires. Ils sont donc scrupuleusement suivis sur le plan médical. Leur aptitude médicale est évaluée lors d’une visite médicale d’admission au moment du recrutement, annuellement lors d’une visite médicale de maintien en activité et également lors des visites de reprise ou des visites occasionnelles.",
