   "dossier": "Dossier B – Mise en place du service SSO pour le système de gestion administratif",
   "mission": "Mission B1 – Renforcer la sécurité des données personnelles et sensibles",
   "page": 6,
   "contexte": "M. Dinant vous demande de participer à la mise en place du chiffrement des données personnelles et sensibles, au niveau de la base de données Medical sans modifier les applications qui l’utilisent. Un scénario de la mise en œuvre a été décrit ; il utilise des vues en langage SQL qui seront nommées exactement comme les tables actuelles. Les données seront chiffrées dans les tables et seront déchiffré es dans la vue. Seuls les utilisateurs habilités pourront utiliser les vues via une authentification par certificat, les accès seront journalisés. Un utilisateur non habilité qui voudrait lire les données ne verrait que des données chiffrées.",
