   "mission": "Mission B2 – Audit de sécurité et intégration",
   "page": 7,
   "contexte": "Élodie a débuté son travail d’intégration du service SSO dans l’interface de programmation et le programme qui l’utilise. Elle rencontre un nouveau souci lors de ses tests de l'interface. Elle a pu obtenir un jeton JWT en s’authentifiant auprès du serveur SSO et après avoir fait sa pause -café durant 15 minutes, elle essaie d’interroger l’interface avec le jeton précédemment obtenu et obtient l’erreur suivante : { \"error\": \"invalid_token\", \"error_description\": \"Token verification failed\" }",
   "texte": "Émettre l’hypothèse la plus probable concernant la nature du problème amenant à cette situation.",
