   "page": 7,
   "contexte": "Afin de gérer l’expiration du jeton JWT initial, une seconde méthode getToken sans paramètre doit être ajoutée dans la classe AuthentificationUtils. Cette nouvelle méthode mettra à jour les jetons à l’aide du jeton de rafraichissement actuel et retournera le jeton rafraichi. Élodie a écrit les spécifications de cette méthode.",
   "texte": "Compléter cette nouvelle méthode.",
