   "page": 8,
   "contexte": "Dans un premier temps, la PSSI prévoit de mener une expérimentation dans une caserne avec un dispositif biométrique dont le gabarit est stocké dans l’appareil . L'administrateur des équipements itinérants se chargera de faire enregistrer les modèles du visage des pompiers volontaires pour cette expérimentation. Un journal des accès à la tablette , mis à jour par l'application Rescousse sera exploité afin de faire le point et de passer éventuellement à l’étape suivante de l’expérimentation. Une version supplémentaire de l’application Rescousse va être gérée, à destination de la caserne expérimentale. Les modifications prévues sont : • accès à l'application au choix par biométrie ou mot de passe avec une limite à trois essais ; • journalisation des accès à l'application ; • remontée de la journalisation sur un serveur du Sdis. Au moyen de la documentation Android, votre collègue Elodie a récupéré et rassemblé le code mettant en œuvre l'authentification biométrique. Elle a créé l'activité LoginBiometrieActivity et défini les classes EntreeLog et DbLogRescousse à utiliser pour enregistrer le journal des accès dans une base de données SQLite. Vous devez compléter le code de ces classes.",
